package earth.terrarium.pastel.data.lang.guidebook.imbrifer;

import net.neoforged.neoforge.common.data.LanguageProvider;

public class GlassCrestToolsEntry {
	public static void addTranslations(LanguageProvider provider) {
		provider.add("book.pastel.guidebook.glass_crest_tools.name", "Glass Crest Tools");
		provider.add("book.pastel.guidebook.glass_crest_tools.page0.text", "Socketing [Malachite Tools](entry://dimension/malachite_tools) with [Moonstone Cores](entry://dimension/moonstone_cores) grants them powerful new abilities.");
		provider.add("book.pastel.guidebook.glass_crest_tools.page1.text", "Shoots out [#](b9bebe)White Ink[#]() which will break blocks on impact. When switching enchantments I can also choose from [Resonance](entry://enchanting/enchantments/resonance).");
		provider.add("book.pastel.guidebook.glass_crest_tools.page2.text", "Deals some of its damage via [#](449900)Magic[#](), which pierces armor. I can also unleash a [#](449900)Ground Slam[#]() that knocks back everything around me. This ability scales with [#](449900)Sweeping[#]().");
		provider.add("book.pastel.guidebook.glass_crest_tools.page2.title", "Ultra Greatsword");
		provider.add("book.pastel.guidebook.glass_crest_tools.page3.text", "After an arrow is loaded, I can overcharge the shot by holding sneak+use to increase the shot's accuracy, speed and damage even further.");
		provider.add("book.pastel.guidebook.glass_crest_tools.page4.text", "The result of combining a Bident and a Pocket Thunderstorm. I can hurl myself into the air and damage everything in my path, even in the driest of deserts! ...as long as I don't run out of Ink. This ability scales with the level of [#](449900)Riptide[#](). *Flying isn't the problem. Landing is.*");
		provider.add("book.pastel.guidebook.glass_crest_tools.page4.title", "Ferocious Bident");
		provider.add("book.pastel.guidebook.glass_crest_tools.page5.text", "The [#](bb00bb)Echo Shards[#]() make this Bident throw an echo of itself when thrown instead, shattering upon impact.\\\n\\\n*This ability scales with [#](449900)Efficiency[#]() and [#](449900)Power[#](), improving yield and damage.*");
		provider.add("book.pastel.guidebook.glass_crest_tools.page5.title", "Fractal Bident");
	}
}
